import torch as t


def solve(logits, ids, p):
    """Score of the actual token at position p."""
    return logits[p - 1, ids[p]].item()

import torch as t


def solve(logits, p):
    """Most likely token id for position p."""
    return logits[p - 1].argmax().item()

import torch as t


def solve(logits, ids):
    """How many next tokens the model's top guess got right."""
    return (logits[:-1].argmax(dim=1) == ids[1:]).sum().item()

import torch as t


def solve(logits, start):
    """How many rows score the phrase."""
    return len(logits[start - 1:-1])

import torch as t


def solve(logits, ids, start):
    """Whether the model's top guess matches every phrase token."""
    return (logits[start - 1:-1].argmax(dim=1) == ids[start:]).all().item()

import torch as t


def solve(logits):
    """Log-probabilities over the vocabulary, row by row."""
    return t.log_softmax(logits, dim=-1)

import torch as t
import einops


def solve(per_token):
    """Phrase log-probability for each text."""
    return einops.reduce(per_token, "batch tok -> batch", "sum")

import torch as t


def solve(rows, r, tok):
    """Log-probability of one token in one row."""
    return t.log_softmax(rows, dim=-1)[r, tok].item()

import torch as t


def solve(rows, r, tok):
    """Probability of one token in one row."""
    return t.log_softmax(rows, dim=-1)[r, tok].exp().item()

import torch as t


def solve(logits, ids, start):
    """Which phrase token was least expected."""
    m = len(ids) - start
    logp = t.log_softmax(logits[start - 1:start - 1 + m], dim=-1)
    return t.argmin(logp[t.arange(m), ids[start:]]).item()

import torch as t


def solve(prefix, reasoning, phrase, b):
    """Prefix, first b reasoning tokens, phrase."""
    return t.cat([prefix, reasoning[:b], phrase])

import torch as t


def solve(before, full):
    """Whether the ids before the phrase survived the joint encoding."""
    return (full[:len(before)] == before).all().item()

import torch as t


def solve(prefix, reasoning, phrase, bounds):
    """Length of each forced sequence."""
    return len(prefix) + bounds + len(phrase)

import torch as t


def solve(before, full):
    """First position where the joint encoding departs from the earlier ids."""
    n = len(before)
    differs = full[:n] != before
    return t.where(differs, t.arange(n), n).min().item()

import torch as t


def solve(before, full_a, full_b):
    """Whether two phrases have equally many tokens here."""
    return len(full_a) == len(full_b)

import torch as t


def solve(prefix, reasoning, b):
    """Ids before the phrase at point b."""
    return t.cat([prefix, reasoning[:b]])

import torch as t


def solve(prefix, reasoning, b, full):
    """Rows of the logits that score the phrase."""
    start = len(prefix) + b
    m = len(full) - start
    return t.arange(start - 1, start - 1 + m)

import torch as t


def solve(prefix, reasoning, b, full, alone):
    """Forced sequence, with the fallback when the joint encoding changed earlier ids."""
    before = t.cat([prefix, reasoning[:b]])
    n = len(before)
    if (full[:n] == before).all():
        return full
    return t.cat([before, alone])

import torch as t


def solve(r, stop_id):
    """Number of tokens before the first stop token."""
    stop = r == stop_id
    return t.where(stop, t.arange(len(r)), len(r)).min().item()

import torch as t


def solve(r, stop_id):
    """Whether the reasoning was closed."""
    return (r == stop_id).any().item()

import torch as t
import einops


def solve(R, stop_id):
    """Reasoning length of every rollout."""
    T = len(R[0])
    return einops.reduce(t.where(R == stop_id, t.arange(T), T), "rollout pos -> rollout", "min")

import torch as t


def solve(is_end, reasoning):
    """How many sentence-ending tokens the reasoning holds."""
    return is_end[reasoning].sum().item()

import torch as t


def solve(is_end, reasoning, b):
    """The sentence-ending token behind a boundary."""
    return reasoning[b - 1].item()

import torch as t


def solve(ids, pad):
    """Length of each sequence in a padded table."""
    return (ids != pad).sum(dim=1)

import torch as t


def solve(vals, mask):
    """Row sums that ignore filler positions."""
    return t.where(mask, vals, 0.0).sum(dim=1)

