import einops


def solve(table, k):
    """Prompt scores from the first k rollouts."""
    return einops.reduce(table[:, :k], "prompt rollout pos -> prompt", "max")

import torch as t
import einops


def solve(table):
    """Score of one prompt."""
    return einops.reduce(table, "rollout pos -> ", "max").item()

import torch as t
import einops


def solve(table):
    """Which rollout produced the prompt's score."""
    return t.argmax(einops.reduce(table, "rollout pos -> rollout", "max")).item()

import torch as t


def solve(table):
    """How many real scores each rollout has."""
    return (table != float("-inf")).sum(dim=1)

import torch as t
import einops


def solve(table, k):
    """Whether the first k rollouts already contain the best score."""
    part = einops.reduce(table[:, :k], "prompt rollout pos -> prompt", "max")
    return part == einops.reduce(table, "prompt rollout pos -> prompt", "max")

import torch as t
import einops


def solve(table, ks):
    """Prompt scores at several rollout counts."""
    return t.stack([einops.reduce(table[:, :k], "prompt rollout pos -> prompt", "max") for k in ks])

import torch as t


def solve(scores, rollout_of, k):
    """Prompt score from a flat batch of forced sequences."""
    return t.where(rollout_of < k, scores, float("-inf")).max().item()

import torch as t


def solve(pos, neg):
    """AUROC of evaluation scores against deployment scores."""
    wins = (pos[:, None] > neg[None, :]).sum()
    ties = (pos[:, None] == neg[None, :]).sum()
    return ((wins + 0.5 * ties) / (len(pos) * len(neg))).item()

import torch as t


def solve(aucs):
    """95% interval from resampled AUROCs."""
    return t.quantile(aucs, t.tensor([0.025, 0.975]))

import torch as t


def solve(pos, neg):
    """Number of pairs the evaluation prompt wins."""
    return (pos[:, None] > neg[None, :]).sum().item()

import torch as t


def solve(pos, neg):
    """Share of deployment prompts each evaluation prompt beats."""
    return (pos[:, None] > neg[None, :]).sum(dim=1) / len(neg)

import torch as t


def solve(n, B, g):
    """Bootstrap index table."""
    return t.randint(0, n, (B, n), generator=g)

import torch as t


def solve(aucs):
    """Whether the monitor is reliably better than chance."""
    return (t.quantile(aucs, 0.025) > 0.5).item()

import torch as t


def solve(pos_a, neg_a, pos_b, neg_b):
    """AUROC difference between two monitors."""
    wa = (pos_a[:, None] > neg_a[None, :]).sum() + 0.5 * (pos_a[:, None] == neg_a[None, :]).sum()
    wb = (pos_b[:, None] > neg_b[None, :]).sum() + 0.5 * (pos_b[:, None] == neg_b[None, :]).sum()
    return ((wa - wb) / (len(pos_a) * len(neg_a))).item()

