import einops


def solve(flags, k):
    """Fraction of the first k rollouts flagged."""
    return einops.reduce(flags[:, :k].float(), "prompt rollout -> prompt", "mean")

import torch as t


def solve(flags, k):
    """Whether any of the first k rollouts was flagged."""
    return flags[:, :k].any(dim=1)

import torch as t


def solve(flags, k):
    """How many prompts score exactly zero on the baseline."""
    return (flags[:, :k].sum(dim=1) == 0).sum().item()
